"""Generate evidence tables and all seven requested reports from completed metrics."""
import csv,datetime,hashlib,json,pathlib,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def dump(p,v):pathlib.Path(p).write_text(json.dumps(v,indent=2,allow_nan=False),encoding='utf-8')
def mean(v):return statistics.mean(v)
def sd(v):return statistics.stdev(v) if len(v)>1 else 0.
def main():
 plan=json.loads((ROOT/'plan54_v1.json').read_text());ev=json.loads((OUT/'evaluation54.json').read_text());ver=json.loads((OUT/'verification54.json').read_text());seal=json.loads((OUT/'SELECTION_SEAL54_V1.json').read_text());assert len(ev['records'])==12
 assert ver['status']=='PASS_INDEPENDENT_NUMPY_KALMAN_AND_ROLLOUT_ARITHMETIC'
 rows=[];groups=[];health=[]
 for r in ev['records']:
  for h in r['horizons']:rows.append({**{k:r[k] for k in ['run','method','task','seed','full_smoothing_R2_train_readout','transition_eigenvalue_mean_absolute_error','state_map_condition']},**{k:v for k,v in h.items() if k!='per_dimension_state_mse'}})
 for task in plan['tasks']:
  for method in ['rp','em']:
   rs=[r for r in ev['records'] if r['task']==task['name'] and r['method']==method];assert len(rs)==3
   groups.append({'task':task['name'],'method':method,'R2_mean':mean([r['full_smoothing_R2_train_readout'] for r in rs]),'R2_sd':sd([r['full_smoothing_R2_train_readout'] for r in rs]),'transition_eigenvalue_error_mean':mean([r['transition_eigenvalue_mean_absolute_error'] for r in rs]),'horizons':[{'h':h,**{key+'_mean':mean([next(z[key] for z in r['horizons'] if z['h']==h) for r in rs]) for key in ['state_mse','auxiliary_observation_mse','conditional_mean_discrepancy']},'state_mse_sd':sd([next(z['state_mse'] for z in r['horizons'] if z['h']==h) for r in rs])} for h in plan['horizons']]})
 for f in seal['fits']:
  path=OUT/'runs'/f['run']/'result.json';r=json.loads(path.read_text());curve=[json.loads(x) for x in (path.parent/'curve.jsonl').read_text().splitlines()];key='native_negative_auxiliary_free_energy' if r['method']=='rp' else 'native_training_log_marginal_likelihood'
  health.append({'run':f['run'],'first_logged_objective':curve[0][key],'last_logged_objective':curve[-1][key],'first_iteration':curve[0]['iteration'],'last_iteration':curve[-1]['iteration'],'runtime_seconds':r['runtime_seconds'],'parameter_count':r['parameter_count']})
 with (OUT/'metrics54.csv').open('w',encoding='utf-8',newline='') as stream:
  writer=csv.DictWriter(stream,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
 summary={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'decision':'NO_NEW_DIRECTION_ACCEPTED_EXISTING_METHOD_QUALIFICATION_ONLY','accepted_directions':0,'baseline_amendment_sha256':sha(ROOT/'plan54_em_amendment_v2.json'),'ordinary_em_correction':'Initial covariance expectation normalization; all other native EM computations retained','failed_native_em_attempt_iterations':400,'groups':groups,'oracle':ev['oracle'],'fit_health':health,'rp_optimizer_updates':sum(f['iterations'] for f in seal['fits'] if f['method']=='rp'),'em_iterations':sum(f['iterations'] for f in seal['fits'] if f['method']=='em'),'fit_wall_seconds_sum':sum(f['runtime_seconds'] for f in seal['fits']),'max_independent_posterior_check_error':ver['max_absolute_smoother_discrepancy'],'plan_sha256':sha(ROOT/'plan54_v1.json'),'evaluation_sha256':sha(OUT/'evaluation54.json'),'verification_sha256':sha(OUT/'verification54.json')}
 dump(OUT/'summary54.json',summary)
 header='# C54: Jointly learned RP-GSSM linear audit\n\nStatus: all 12 fixed-budget fits (RP native; ordinary LGSSM EM with the explicitly qualified initial-covariance normalization correction), training-only state maps, causal heldout scoring and independent numerical checks completed. This is a paper-recipe reconstruction using pinned native components; it is not the original full hyperparameter sweep or visual benchmark reproduction.\n\n'
 table='| Task | Model | Full smoothing R2, train-only map | Mean eigenvalue error | h=1 state MSE | h=10 state MSE | h=50 state MSE |\n|---|---|---:|---:|---:|---:|---:|\n'
 for g in groups:
  get=lambda h:next(z['state_mse_mean'] for z in g['horizons'] if z['h']==h)
  table+=f"|{g['task']}|{g['method']}|{g['R2_mean']:.6f} +/- {g['R2_sd']:.6f}|{g['transition_eigenvalue_error_mean']:.6f}|{get(1):.6f}|{get(10):.6f}|{get(50):.6f}|\n"
 cond='| Task | Model | h=1 conditional-mean discrepancy | h=10 discrepancy | h=50 discrepancy |\n|---|---|---:|---:|---:|\n'
 for g in groups:
  get=lambda h:next(z['conditional_mean_discrepancy_mean'] for z in g['horizons'] if z['h']==h)
  cond+=f"|{g['task']}|{g['method']}|{get(1):.6g}|{get(10):.6g}|{get(50):.6g}|\n"
 oracle='| Task | h=1 oracle state MSE | h=10 | h=50 |\n|---|---:|---:|---:|\n'
 for g in ev['oracle']:
  get=lambda h:next(z['state_mse'] for z in g['horizons'] if z['h']==h)
  oracle+=f"|{g['task']}|{get(1):.6f}|{get(10):.6f}|{get(50):.6f}|\n"
 notes=('The ordinary EM baseline uses the same native E-step, regression updates and 200-iteration fit loop, with only initial covariance corrected to sum_Ezz/N - outer(sum_Ez/N,sum_Ez/N). The uncorrected seed0 first M-step was indefinite; two failed 200-iteration attempts were excluded and retained. Independent training-only qualification verified the corrected moments, all other parameters identical, and increasing finite likelihood. The protocol amendment predates heldout/state-readout evaluation. No upstream package/source was edited. See plan54_em_amendment_v2.json and outputs/QUALIFICATION_EM_FIX54_V1.json.\n\n'
        'The three seeds vary initialization on one fixed dataset per dimension; they are not independent domains or independent data draws. All state labels enter only post-training diagnostic maps. Full-sequence smoothing uses future observations relative to individual times; causal prediction uses only the first 50 observations. Auxiliary observation maps use training observations alone and are applied equally to both learned models. Long-horizon factual MSE includes irreducible process noise; conditional-mean discrepancy measures deviation from the oracle conditional expectation. No significance or broad generalization claim is made.\n\n'
        'All source files retain their pinned SHA256. Independent NumPy Kalman/RTS checks account explicitly for the RP source\'s fixed 1e-5 I addition to reported smoothed covariances. This does not equate the Gaussian auxiliary surrogate with the proper normalized RPM posterior. All model and readout checkpoint hashes are unchanged after evaluation.\n\n')
 results=header+table+'\n'+cond+'\n'+oracle+'\n'+notes+f"RP optimizer updates: {summary['rp_optimizer_updates']}; native EM iterations: {summary['em_iterations']}; sum of fit wall times: {summary['fit_wall_seconds_sum']:.3f}s. No GPU training is claimed. Independent posterior arithmetic maximum absolute error after the explicitly documented native covariance correction: {summary['max_independent_posterior_check_error']:.3g}.\n\nRaw arrays and checkpoints remain on server storage. `outputs/metrics54.csv`, `outputs/evaluation54.json`, `outputs/verification54.json` and immutable model/readout seals provide the compact evidence.\n"
 docs={
 'experimental_results.md':results,
 'literature_review.md':header+'[RP-GSSM, ICML 2026](https://proceedings.mlr.press/v306/hromadka26a.html) already jointly learns recognition and linear-Gaussian latent dynamics without a parametric decoder. Appendix D.3/Table S1/E define the linear recipe used here. The paper discusses its auxiliary approximation and asymptotic identifiability; neither approximate inference nor latent dynamics learning is a new research gap. C2 had already executed native components with a fixed correct prior and found existing generative/numerical controls repaired its rare-event diagnostic. C54 addresses the distinct complete prior-learning recipe.\n\n[Native source pin](https://github.com/gatsby-sahani/rp-gssm/tree/a75225d5edceb972bb872dc9a335608733567dd4) contains two visual demos but no attached image datasets or exact linear launcher. The available source, cached paper hash and new protocol are retained separately. LGSSM EM is established prior art, executed here through Dynamax 0.1.5. This audit does not present Kalman inference, eigenvalue diagnostics, state readouts, or reconstruction-free learning as inventions.\n',
 'baseline_registry.md':header+'| Baseline | Source/version | Executed scope | Status |\n|---|---|---|---|\n| RP-GSSM | a75225d5edceb972bb872dc9a335608733567dd4 | Learned full A + native linear recognition, constant diagonal site precision, 2 tasks x 3 initializations x 10,000 updates | Complete |\n| LGSSM EM | Dynamax 0.1.5 plus initial-moment normalization fix | 2 tasks x 3 initializations x 200 native EM iterations | Complete |\n| True-parameter Kalman oracle | Original generator A,Q,C,R,m1,Q1 | Causal conditional mean for the same first 50 observations | Complete; oracle only |\n| Official RP visual demos | Same public source | Source/configuration review, image files not attached | Not reproduced |\n\n'+notes,
 'negative_evidence.md':header+'No new research direction is accepted from these two synthetic tasks. A per-model error does not establish a field-wide deficiency, and an already available LGSSM repair does not justify renaming it as a new world model. High state-decoding R2 alone cannot establish accurate propagation; all forecast and conditional-mean results must be considered. Low factual long-horizon R2 alone cannot establish failure because the oracle itself loses predictability.\n\nExecution history is preserved: first Start-Process launch exited before preparation with empty logs; persistent WMI preparation initially failed because the remote staging lacked the two pinned demo notebooks; filling only those missing files made all 21 source hashes match. No previous source file was replaced. The first inference qualification exposed the source\'s explicit 1e-5 covariance correction; the versioned evaluator checks that term explicitly. The original ordinary EM M-step also omitted a sample-count normalization in its initial covariance. It produced NaNs after the first update; the standard moment fix was independently qualified before completing baseline fits. These are implementation/checking issues, not a new model failure mechanism. No formal model/objective/hyperparameter changes were made to obtain favorable heldout scores.\n\n'+cond,
 'hypothesis_space.md':header+'| Hypothesis | Discriminating evidence | Current scope |\n|---|---|---|\n| A learned representation necessarily lacks usable transition structure | Learned native A, eigenvalues and causal forecasts; compare existing EM and oracle | Cannot be asserted from aggregate decoding scores |\n| A weak long forecast means the model forgot the mechanism | Conditional-mean discrepancy versus irreducible oracle MSE | Factual and conditional errors separated |\n| An apparent success comes from fitting state maps to heldout labels | Immutable training-only readout seal before heldout scoring | Training-only maps used for all forecasts |\n| Native Gaussian numerical error causes the result | Independent NumPy KF/RTS with explicit source jitter and matrix-power checks | Numerical checks passed; does not validate RPM approximation |\n| Two linear tasks establish a reusable new world-model research gap | Requires distinct nonlinear/real evidence and close existing controls | Rejected: current evidence is insufficient |\n\n'+table,
 'research_ideas.md':header+'No publication-ready idea is recommended. The candidate question is whether state recovery and propagation quality separate under complete unsupervised learning, after controlling information, uncertainty and optimization. This is an audit question already related to extensive state-space literature, not an innovation claim. A new method is unjustified until an existing strong model fails in a scientifically meaningful setting and routine remedies are excluded. C54 supplies a stronger executable reference and a conditional-noise-aware diagnosis for that decision.\n\n'+cond,
 'final_research_direction.md':header+'**Research Question:** Does jointly learned latent recognition recover transition structure that remains useful for causal multi-step prediction, rather than only for full-sequence state readout?\n\n**Evidence:** Complete native-model recipe and strong ordinary LGSSM fits on two in-model synthetic tasks, with frozen training-only maps and oracle conditional means.\n\n'+table+'\n'+cond+'\n**Existing Methods:** RP-GSSM and LGSSM EM are established mechanisms. The current comparison cannot support a claim that existing world models generally cannot learn reusable dynamics.\n\n**Proposed Idea:** None accepted. Do not introduce a new architecture from this qualification alone.\n\n**Falsification:** Existing models matching useful conditional predictions refute a broad missing-capability claim. A deficit repaired by ordinary exact-inference LGSSM is model-specific evidence, not proof of a new general gap.\n\n**Feasibility:** Both native implementations ran on the server\'s existing CPU runtime. Signals, checkpoints and arrays use the authorized large disk. Two synthetic data draws and three model initializations do not establish real-world generalization.\n\n**Next Experiment:** The PRO-DYN source/task audit is complete (PRODYN_SCOPE_AUDIT54.md): it is retained as a forecasting parameterization reference, not a latent-state benchmark. Select the next nonlinear or real-system comparison from an actual released state-learning input contract and a competent existing control. That selection remains open; it is not presented as a selected final research direction. Avoid repeating the fixed-prior alarm diagnostic.\n\n**Decision:** No new direction accepted; the overarching discovery objective remains active.\n'}
 docs['README.md']=results+'\nExecution contract: see `PROTOCOL.md` and `REPRODUCE.md`.\n'
 for name,text in docs.items():assert not (ROOT/name).exists();(ROOT/name).write_text(text,encoding='utf-8')
 dump(OUT/'REPORT_MANIFEST54_V1.json',{'utc':summary['utc'],'status':'ALL_12_FITS_AND_NUMERICAL_AUDIT_COMPLETE','reports':{n:sha(ROOT/n) for n in docs},'summary_sha256':sha(OUT/'summary54.json'),'accepted_research_directions':0,'overall_goal':'ACTIVE_NOT_ACHIEVED'})
 print(json.dumps(summary),flush=True)
if __name__=='__main__':main()
